 const input=d.querySelector('#spoken-answer'),mic=d.querySelector('.mic-button'),status=d.querySelector('.guide-message'),code=d.querySelector('.guide-code');code.oninput=()=>sessionStorage.setItem('solve-ai-code',code.value);const persistDraft=()=>{if(p){g.draft=input.value;save()}else d._newDraft=input.value};input.oninput=()=>{persistDraft();acknowledgeGuideQuestion(d,g)};d.querySelector('#show-new-question')?.addEventListener('click',()=>revealGuideQuestion(d));
